import{_ as e,o,c as t,a2 as l}from"./chunks/framework.BY72S51x.js";const r="/aibutler/docs-versions/v1.1.9/img/chat-chart.png",b=JSON.parse('{"title":"聊天窗口能显示什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/display.md","filePath":"guide/display.md"}'),i={name:"guide/display.md"};function p(c,a,s,h,d,n){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="聊天窗口能显示什么" tabindex="-1">聊天窗口能显示什么 <a class="header-anchor" href="#聊天窗口能显示什么" aria-label="Permalink to &quot;聊天窗口能显示什么&quot;">​</a></h1><p>人格的回复不只是文字。聊天窗口能直接画出表格、图表、流程图、公式、动画，还能放带输入框和按钮的表单。</p><p><strong>你不用学任何写法</strong>，跟它说你想看什么就行。</p><p><img src="'+r+'" alt="表格和柱状图"></p><div class="tip custom-block"><p class="custom-block-title">工具调用默认不列出来</p><p>人格干活时调用的工具，默认不在对话里一行行列出来，正在做什么看窗口底部的状态栏。想看，打开系统设置 →「通用」→「工具调用」，勾「在对话里显示」。同一页的「小贴士」管每次打开时弹的那条用法提示，可以关掉，也可以点「现在看一条」。</p></div><h2 id="表格" tabindex="-1">表格 <a class="header-anchor" href="#表格" aria-label="Permalink to &quot;表格&quot;">​</a></h2><blockquote><p>把这周的开销按类别列个表。</p></blockquote><p>适合对比、清单、账目。</p><h2 id="图表" tabindex="-1">图表 <a class="header-anchor" href="#图表" aria-label="Permalink to &quot;图表&quot;">​</a></h2><blockquote><p>把这半年每个月的支出画成柱状图。</p></blockquote><blockquote><p>用折线图看看体重变化。</p></blockquote><p>柱状图、折线图、饼图都可以。</p><h2 id="流程图和关系图" tabindex="-1">流程图和关系图 <a class="header-anchor" href="#流程图和关系图" aria-label="Permalink to &quot;流程图和关系图&quot;">​</a></h2><blockquote><p>用流程图画一下报销要走哪几步。</p></blockquote><blockquote><p>画个图说明这几个人格是怎么分工的。</p></blockquote><h2 id="公式" tabindex="-1">公式 <a class="header-anchor" href="#公式" aria-label="Permalink to &quot;公式&quot;">​</a></h2><blockquote><p>把复利公式写出来，解释每个字母。</p></blockquote><p>数学、物理公式会排成正规的样子。</p><h2 id="图形和动画" tabindex="-1">图形和动画 <a class="header-anchor" href="#图形和动画" aria-label="Permalink to &quot;图形和动画&quot;">​</a></h2><blockquote><p>画一个太阳系示意图，让行星转起来。</p></blockquote><p>适合讲原理、做演示。</p><h2 id="表单和按钮" tabindex="-1">表单和按钮 <a class="header-anchor" href="#表单和按钮" aria-label="Permalink to &quot;表单和按钮&quot;">​</a></h2><p>需要你填信息或做选择时，人格会直接在聊天里放输入框、下拉框、单选、多选和按钮，你点一点就行，不用打字。比如：</p><blockquote><p>帮我订个提醒，时间和内容你问我。</p></blockquote><p>它会弹出一个小表单让你填时间和内容，点按钮提交。</p><h2 id="小工具" tabindex="-1">小工具 <a class="header-anchor" href="#小工具" aria-label="Permalink to &quot;小工具&quot;">​</a></h2><p>想要一直留着用的界面，比如记账本、待办看板、单词卡，让它做成 <a href="/aibutler/docs-versions/v1.1.9/guide/plugins.html">插件</a>。插件可以钉在窗口边上，随时点开。</p><h2 id="左右布局和「收藏夹」" tabindex="-1">左右布局和「收藏夹」 <a class="header-anchor" href="#左右布局和「收藏夹」" aria-label="Permalink to &quot;左右布局和「收藏夹」&quot;">​</a></h2><p>点顶栏的 ◫ 可以在「上下」和「左右」两种布局之间切换，每个人格各记各的。</p><p>左右布局时，提醒、待办和快捷按钮挪到左栏，聊天在中间，右栏是「收藏夹」：跟人格说「把这个放收藏夹」，那条回复就会存一份在这里，比如定下的方案、算出来的结论、交给你的文件路径。对话滚上去很远也不怕：点一条就地展开全文，旁边的小按钮能跳回原消息，不想要的可以删掉。</p><p>两栏的宽度可以拖：按住栏和聊天之间的那条边左右拖。拖到最边上，栏就收成一条细边，不占地方；收着的时候收藏照样往里存，右边细边上会出现新添了几条。点一下细边或者往外拖，栏就回来了。</p><p>在上下布局时，收藏夹新添了内容，◫ 上会出现一个数字，切到左右布局就能看到。窗口窄于 1100 像素时自动按上下排，◫ 也会藏起来，拉宽了再出现。</p>',32)])])}const q=e(i,[["render",p]]);export{b as __pageData,q as default};
